# frozen_string_literal: true

require_relative "test_helper"

# Publications page generated by jekyll-scholar from assets/bibliography/publications.bib.
class PublicationsTest < Minitest::Test
  include SiteHelpers

  BIB_PATH = File.expand_path("../assets/bibliography/publications.bib", __dir__)

  def setup
    @content = page("publications/index.html").at_css(".page__content")
    @entries = @content.css(".publication")
  end

  def test_every_bibtex_entry_is_rendered
    assert_equal bibtex_keys.size, @entries.size
    refute_empty @entries
  end

  def test_bibtex_keys_are_unique
    assert_equal bibtex_keys.uniq, bibtex_keys
  end

  def test_entries_are_grouped_by_year_most_recent_first
    years = @content.css("h2.bibliography").map { |heading| heading.text.to_i }
    assert_operator years.size, :>, 1
    assert_equal years.sort.reverse, years
    assert_equal years.uniq, years
  end

  def test_site_owner_is_highlighted_in_every_entry
    @entries.each do |entry|
      assert_equal "Hromei, C. D.", entry.at_css("strong")&.text, "owner not highlighted in: #{entry.text.strip[0, 80]}"
    end
  end

  def test_every_entry_links_to_the_paper_over_https
    @entries.each do |entry|
      link = entry.at_css(".publication__links a")
      refute_nil link, "missing paper link in: #{entry.text.strip[0, 80]}"
      assert_equal "Paper", link.text
      assert link["href"].start_with?("https://"), "paper link is not https: #{link['href']}"
    end
  end

  def test_citations_do_not_spell_out_urls
    @entries.each do |entry|
      reference = entry.at_css(".publication__reference").text
      refute_match(%r{https?://}, reference, "raw URL in: #{reference.strip[0, 80]}")
    end
  end

  def test_paper_link_goes_to_the_pdf_when_the_entry_has_one
    bibtex_entries.each do |key, fields|
      next unless fields["pdf"]

      assert_equal fields["pdf"], rendered(key).at_css(".publication__links > a")["href"]
    end
  end

  def test_abstract_is_shown_for_every_entry_that_has_one
    with_abstract = bibtex_entries.select { |_key, fields| fields["abstract"] }
    assert_operator with_abstract.size, :>=, 20
    with_abstract.each_key do |key|
      abstract = rendered(key).at_css("details.publication__abstract p")
      refute_nil abstract, "abstract not rendered for #{key}"
      assert_operator abstract.text.strip.length, :>, 200
    end
    assert_equal with_abstract.size, @content.css("details.publication__abstract").size
  end

  def test_abstracts_have_no_leftover_latex_escapes
    @content.css("details.publication__abstract p").each do |abstract|
      refute_match(/\\[&%$#_]|[{}]/, abstract.text)
    end
  end

  def test_every_entry_can_be_cited_as_bibtex_without_site_only_fields
    bibtex_entries.each_key do |key|
      bibtex = rendered(key).at_css("details.publication__cite code")
      refute_nil bibtex, "BibTeX not rendered for #{key}"
      assert_match(/\A@\w+\{#{Regexp.escape(key)},/, bibtex.text.strip)
      assert_includes bibtex.text, "author = {"
      %w[abstract pdf code award].each do |field|
        refute_match(/^\s*#{field}\s*=/, bibtex.text, "#{field} must not appear in the BibTeX of #{key}")
      end
    end
  end

  # A BibTeX line is wider than a phone screen: the open block must scroll inside itself.
  def test_open_details_cannot_grow_wider_than_the_page
    %w[assets/css/main.css assets/css/main-dark.css].each do |css|
      rule = File.read(site_path(css), encoding: "utf-8")[/\.publication__links details\[open\]\{([^}]*)\}/, 1]
      refute_nil rule, "rule for open details missing in #{css}"
      assert_includes rule, "min-width:0"
      assert_includes rule, "max-width:100%"
    end
  end

  def test_phd_thesis_is_listed_with_its_pdf
    thesis = rendered("hromei2025thesis")
    assert_includes thesis.text, "Situated Natural Language Understanding in HRI via LLMs"
    assert thesis.at_css(".publication__links > a")["href"].end_with?(".pdf")
  end

  def test_best_paper_awards_are_shown
    awarded = @entries.select { |entry| entry.at_css(".publication__award") }
    assert_equal 2, awarded.size
    assert(awarded.any? { |entry| entry.text.include?("EVALITA 2023") })
    assert(awarded.any? { |entry| entry.text.include?("NL4AI 2022") })
  end

  def test_bibtex_file_is_published_and_linked
    assert File.exist?(site_path("assets/bibliography/publications.bib")), "BibTeX download not published"
    hrefs = @content.css("a").map { |a| a["href"] }
    assert_includes hrefs, "/assets/bibliography/publications.bib"
  end

  private

  def bibtex_keys
    bibtex_entries.keys
  end

  # { key => { field => value } } for the single-line fields of every entry in the BibTeX source.
  def bibtex_entries
    @bibtex_entries ||= File.read(BIB_PATH, encoding: "utf-8").scan(/^@\w+\{([^,]+),(.*?)^\}/m).to_h do |key, body|
      [key, body.scan(/^\s*(\w+)\s*=\s*\{(.*)\},?$/).to_h]
    end
  end

  # Rendered entry for a BibTeX key (the "Cite" block starts with it).
  def rendered(key)
    entry = @entries.find { |candidate| candidate.at_css("details.publication__cite code").text.include?("{#{key},") }
    refute_nil entry, "entry #{key} not rendered"
    entry
  end
end
